<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><?php $urlFor = static function (array $changes = []) use ($viewMode, $selectedTerm, $query): string { $params = ['view' => $viewMode, 'term' => $selectedTerm['id'] ?? null, 'q' => $query !== '' ? $query : null]; foreach ($changes as $key => $value) { $params[$key] = $value; } return current_url() . '?' . http_build_query(array_filter($params, static fn ($value): bool => $value !== null && $value !== '')); }; ?>
