<?php else: ?><div class="card-grid"><?php foreach ($pieces as $piece): ?><?php $fileExtension = mb_strtoupper((string) pathinfo((string) ($piece['original_filename'] ?? ''), PATHINFO_EXTENSION)); ?><?php $fileExtension = $fileExtension !== '' ? $fileExtension : mb_strtoupper((string) $piece['type']); ?><article class="card piece-card piece-state-<?= esc($piece['display_state']) ?>"><div class="piece-card-flags"><label class="piece-check" title="<?= esc($piece['original_filename'] ?: $piece['title']) ?>"><input type="checkbox" name="piece_ids[]" value="<?= esc($piece['id']) ?>" aria-label="Selecionar <?= esc($piece['title']) ?>" <?= $piece['status'] !== 'draft' ? 'disabled' : '' ?>><span class="file-extension"><?= esc($fileExtension) ?></span></label><span class="access-badge"><?php if ($piece['display_state_locked']): ?><span aria-hidden="true">🔒</span> <?php endif ?><?= esc($piece['display_state_label']) ?></span></div><a class="piece-thumbnail" href="<?= site_url('pecas/'.$piece['id']) ?>" aria-label="Abrir <?= esc($piece['title']) ?>"><img src="<?= site_url('pecas/'.$piece['id'].'/miniatura') ?>" alt="" width="640" height="360" loading="lazy"></a><div class="piece-card-content"><h3><a href="<?= site_url('pecas/'.$piece['id']) ?>"><?= esc($piece['title']) ?></a></h3><div class="piece-keywords" aria-label="Palavras-chave"><?php if ($piece['keywords']): ?><?php foreach ($piece['keywords'] as $keyword): ?><a href="<?= esc($urlFor(['term' => $keyword['id']])) ?>"><?= esc($keyword['label']) ?></a><?php endforeach ?><?php else: ?><span class="no-keywords">Sem palavras-chave</span><?php endif ?></div></div></article><?php endforeach ?></div><?php endif ?></form>
